3|import { PicturePanel } from "./picture-panel";
4|import { Reader } from "./reader";
5|import type { SceneMeta } from "./reader";
6|
7|// Static server component: book text prerenders at build time. Only scene
8|// ids, titles, and emotion triples pass to the client container.
9|export default function Home() {
10|  const { book, scenes } = loadOzBook();
11|  const model = buildReaderModel(book, { scenes });
12|  const meta: SceneMeta[] = model.chapters.flatMap((c) =>
13|    c.scenes.map((s) => ({ id: s.id, title: s.title, emotion: s.emotion })),
14|  );
15|
16|  return (
17|    <>
18|      <header className="topbar">Lectoria</header>
19|      <div className="shell">
20|        <main className="book">
21|          <h1>{model.title}</h1>
22|          <Reader scenes={meta}>
23|            {model.chapters.map((chapter) => (
24|              <div key={chapter.ch}>
25|                <h2>
26|                  Chapter {chapter.ch}: {chapter.title}
27|                </h2>
28|                {chapter.scenes.map((scene) => (
29|                  <section key={scene.id} data-scene-id={scene.id} aria-label={scene.title}>
30|                    {scene.paragraphs.map((p) => (
31|                      <p key={p.id} id={p.id} data-n={p.n}>
32|                        {p.text}
33|                      </p>
34|                    ))}
35|                  </section>
36|                ))}
37|              </div>
38|            ))}
39|          </Reader>
40|        </main>
41|        <aside className="companion" aria-label="Companion">
42|          <PicturePanel bookId={model.bookId} textVersion={model.textVersion} />
43|        </aside>
44|      </div>
45|    </>
46|  );
