24|async function postImage(body: unknown): Promise<ImageResponse> {
25|  const res = await fetch("/api/images", {
26|    method: "POST",
27|    headers: { "Content-Type": "application/json" },
28|    body: JSON.stringify(body),
29|  });
30|  return (await res.json()) as ImageResponse;
31|}
32|
33|// Companion panel: illustrates the selected passage or the current scene.
34|// The client sends ordinals and ids only, never text.
35|export function PicturePanel({ bookId, textVersion }: { bookId: string; textVersion: string }) {
36|  const [card, setCard] = useState<Card>({ phase: "idle" });
37|  const [selTop, setSelTop] = useState<number | null>(null);
38|  const [selLeft, setSelLeft] = useState<number | null>(null);
39|  const pollLeft = useRef(0);
40|
41|  const request = useCallback(
42|    async (body: unknown) => {
43|      setCard({ phase: "loading" });
44|      pollLeft.current = POLL_MAX;
45|      for (;;) {
46|        let res: ImageResponse;
47|        try {
48|          res = await postImage(body);
49|        } catch {
50|          setCard({ phase: "error", message: "No se pudo generar la imagen. Vuelve a intentarlo." });
51|          return;
52|        }
53|        if (res.status === "ready") {
54|          setCard({ phase: "ready", url: res.url, caption: res.caption, cached: res.cached });
55|          return;
56|        }
57|        if (res.status === "error") {
58|          setCard({ phase: "error", message: res.message });
59|          return;
60|        }
61|        pollLeft.current -= 1;
62|        if (pollLeft.current <= 0) {
63|          setCard({
64|            phase: "error",
65|            message: "La imagen tarda más de lo esperado. Vuelve a intentarlo.",
66|          });
67|          return;
68|        }
69|        await new Promise((done) => setTimeout(done, POLL_MS));
70|      }
71|    },
72|    [],
73|  );
74|
75|  useEffect(() => {
76|    const onChange = () => {
77|      const sel = window.getSelection();
78|      const book = document.querySelector("main.book");
79|      if (!sel || sel.isCollapsed || !book || !sel.rangeCount) {
80|        setSelTop(null);
81|        return;
82|      }
83|      if (!book.contains(sel.anchorNode) && !book.contains(sel.focusNode)) {
84|        setSelTop(null);
85|        return;
86|      }
87|      const rect = sel.getRangeAt(0).getBoundingClientRect();
88|      setSelTop(rect.top + window.scrollY - 44);
89|      setSelLeft(Math.min(rect.left + window.scrollX, window.scrollX + window.innerWidth - 220));
90|    };
91|    document.addEventListener("selectionchange", onChange);
92|    return () => document.removeEventListener("selectionchange", onChange);
93|  }, []);
94|
95|  const illustratePassage = useCallback(() => {
96|    const sel = window.getSelection();
97|    const book = document.querySelector("main.book");
98|    if (!sel || !book) return;
99|    const entries: ParaEntry[] = [...book.querySelectorAll("p[id][data-n]")].map((el) => ({
100|      id: el.id,
101|      n: Number(el.getAttribute("data-n")),
102|    }));
103|    const n = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
104|    setSelTop(null);
105|    if (n === null || !Number.isInteger(n)) return;
106|    void request({ kind: "passage", bookId, textVersion, n });
107|  }, [bookId, textVersion, request]);
108|
109|  const illustrateScene = useCallback(() => {
110|    const sections = [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map(
111|      (el) => ({ id: el.dataset.sceneId ?? "", top: el.getBoundingClientRect().top }),
112|    );
113|    const sceneId = pickActiveScene(sections, window.innerHeight / 3);
114|    if (!sceneId) return;
115|    void request({ kind: "scene", bookId, textVersion, sceneId });
116|  }, [bookId, textVersion, request]);
117|
118|  return (
119|    <div className="picture">
120|      <button type="button" className="picture-scene" onClick={illustrateScene} aria-label="Ilustrar escena">
121|        Ilustrar escena
122|      </button>
123|      {card.phase === "ready" ? (
124|        <figure className="picture-card">
125|          <img src={card.url} alt={card.caption} className="picture-img" />
126|          <figcaption>
127|            {card.caption} <span className="picture-flag">{card.cached ? "Guardada" : "Nueva"}</span>
128|          </figcaption>
129|        </figure>
130|      ) : card.phase === "loading" ? (
131|        <div className="picture-loading" role="status" aria-label="Ilustrando">
132|          Ilustrando…
133|        </div>
134|      ) : card.phase === "error" ? (
135|        <p className="picture-error" role="alert">
136|          {card.message}
137|        </p>
138|      ) : null}
139|      <p className="picture-note">El chat llega más adelante.</p>
140|      {selTop !== null && selLeft !== null ? (
141|        <button
142|          type="button"
143|          className="picture-float"
144|          style={{ top: selTop, left: selLeft }}
145|          onClick={illustratePassage}
146|          aria-label="Ilustrar este pasaje"
147|        >
148|          Ilustrar este pasaje
149|        </button>
150|      ) : null}
151|    </div>
152|  );
