1|// Session track selection. Pure: no env, no fetch, no audio.
2|import type {
3|  MusicConfig,
4|  MusicManifest,
5|  MusicSelection,
6|  PersistedMusicPrefs,
7|  Rng,
8|  SceneSignal,
9|  Soundtrack,
10|  Track,
11|} from "./music-types";
12|import { dominantEmotion, rankTracks, resolveConfig } from "./music-similarity";
13|
14|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
15|// emotion, in score order, wrapping and skipping the current track. When
16|// the current track has another emotion, start at the top candidate. With
17|// no other same-emotion track, fall back to the best track overall that
18|// Style scope for every pick, minus playlist-only tracks. Playlist tracks
19|// never enter emotion selection, so the filter lives here, not in callers.
20|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
21|  const audible = manifest.tracks.filter((t) => t.playlistOnly !== true);
22|  if (selection.style === null) return audible;
23|  return audible.filter((t) => t.style === selection.style);
24|}
25|
26|// Home set in soundtrack mode: the session soundtrack, or the whole
27|// style set when none is set yet.
28|export function homeTracks(selection: MusicSelection, styleTracks: Track[]): Track[] {
29|  if (selection.soundtrackId === null) return styleTracks;
30|  const home = styleTracks.filter((t) => t.soundtrack === selection.soundtrackId);
31|  return home.length > 0 ? home : styleTracks;
32|}
33|
34|// "Cambiar track": the next same-emotion track in score order, wrapping
35|// and skipping the current. In soundtrack mode it stays inside the
36|// current track's soundtrack first, then tries the same emotion in other
37|// same-style soundtracks, then the best same-style track overall. In
38|// random mode it ranges over all same-style soundtracks at once. A null
39|// scene cycles the style set in id order. One track or none gives null.
40|export function nextTrack(
41|  scene: SceneSignal | null,
42|  manifest: MusicManifest,
43|  currentTrackId: string | null,
44|  override?: Partial<MusicConfig>,
45|  selection?: MusicSelection | null,
46|): Track | null {
47|  const scope =
48|    selection == null
49|      ? manifest.tracks.filter((t) => t.playlistOnly !== true)
50|      : candidatesFor(selection, manifest);
51|  if (scope.length <= 1) return null;
52|  const config = resolveConfig(override);
53|  const scoped = { ...manifest, tracks: scope };
54|  if (scene === null) {
55|    const ids = [...scope].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
56|    const at = ids.findIndex((t) => t.id === currentTrackId);
57|    return ids[(at + 1) % ids.length] as Track;
58|  }
59|  const ranked = rankTracks(scene, scoped, config);
60|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
61|  const others = same.filter((t) => t.id !== currentTrackId);
62|  if (others.length > 0) {
63|    if (selection?.mode === "random") {
64|      const at = same.findIndex((t) => t.id === currentTrackId);
65|      if (at >= 0) return same[(at + 1) % same.length] as Track;
66|      return same[0] as Track;
67|    }
68|    const current = scope.find((t) => t.id === currentTrackId) ?? null;
69|    const home = current ? same.filter((t) => t.soundtrack === current.soundtrack) : [];
70|    const homeOthers = home.filter((t) => t.id !== currentTrackId);
71|    if (homeOthers.length > 0) {
72|      const at = home.findIndex((t) => t.id === currentTrackId);
73|      if (at >= 0) return home[(at + 1) % home.length] as Track;
74|      return home[0] as Track;
75|    }
76|    const at = same.findIndex((t) => t.id === currentTrackId);
77|    if (at >= 0) return same[(at + 1) % same.length] as Track;
78|    return same[0] as Track;
79|  }
80|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
81|}
82|
83|// Random mode draw: same-style tracks with the scene's dominant emotion
84|// (or the whole style set when none matches), scored, kept within
85|// randomTolerance of the best. The current track stays when eligible;
86|// otherwise the draw skips it when an alternative exists.
87|export function pickRandomTrack(
88|  cands: Track[],
89|  scene: SceneSignal | null,
90|  excludeId: string | null,
91|  rng: Rng,
92|  override?: Partial<MusicConfig>,
93|): Track | null {
94|  if (cands.length === 0) return null;
95|  if (scene === null) {
96|    const ids = [...cands].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
97|    const at = ids.findIndex((t) => t.id === excludeId);
98|    return ids[(at + 1) % ids.length] as Track;
99|  }
100|  const config = resolveConfig(override);
101|  const scoped = { version: 3, styles: [], soundtracks: [], playlists: [], tracks: cands };
102|  const ranked = rankTracks(scene, scoped, config);
103|  const dom = dominantEmotion(scene);
104|  const pool = ranked.filter((t) => t.emotion === dom);
105|  const kept = (pool.length > 0 ? pool : ranked).map((t) => ({
106|    track: t,
107|    score: config.similarity(scene, t, config.weights),
108|  }));
109|  const best = kept[0]?.score ?? 0;
110|  const eligible = kept.filter((e) => e.score >= best - config.randomTolerance);
111|  const current = excludeId !== null ? eligible.find((e) => e.track.id === excludeId) : undefined;
112|  if (current) return current.track;
113|  const rest = eligible.filter((e) => e.track.id !== excludeId);
114|  const drawFrom = rest.length > 0 ? rest : eligible;
115|  if (drawFrom.length === 0) return null;
116|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as { track: Track }).track;
117|}
118|
119|// Distinct hand-labeled emotions on a soundtrack, ignoring playlist-only
120|// tracks. The initial session soundtrack is the one covering most
121|// emotions, ties by lower id.
122|export function soundtrackCoverage(manifest: MusicManifest, soundtrackId: string): number {
123|  return new Set(
124|    manifest.tracks
125|      .filter((t) => t.soundtrack === soundtrackId && t.playlistOnly !== true)
126|      .map((t) => t.emotion),
127|  ).size;
128|}
129|
130|// Best emotion coverage among the given soundtracks, ties by lower id.
131|// Soundtracks with no audible tracks never win.
132|function bestCoverageSoundtrack(manifest: MusicManifest, soundtracks: Soundtrack[]): string | null {
133|  let best: string | null = null;
134|  let bestCover = -1;
135|  for (const s of soundtracks) {
136|    if (!manifest.tracks.some((t) => t.soundtrack === s.id && t.playlistOnly !== true)) continue;
137|    const cover = soundtrackCoverage(manifest, s.id);
138|    if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
139|      best = s.id;
140|      bestCover = cover;
141|    }
142|  }
143|  return best;
144|}
145|
146|export function pickInitialSoundtrack(
147|  manifest: MusicManifest,
148|  persistedId: string | null,
149|): string | null {
150|  if (persistedId !== null && manifest.soundtracks.some((s) => s.id === persistedId)) {
151|    return persistedId;
152|  }
153|  return bestCoverageSoundtrack(manifest, manifest.soundtracks);
154|}
155|
156|// True when the style has at least one emotion-selectable track. The style
157|// selector uses this, so a style with only playlist tracks stays hidden.
158|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
159|  return manifest.tracks.some((t) => t.style === style && t.playlistOnly !== true);
160|}
161|
162|// Session defaults on load. A stored style with no tracks and a stored
163|// soundtrack outside the stored style both fall back to the defaults.
164|export function resolveInitialSelection(
165|  manifest: MusicManifest,
166|  persisted: PersistedMusicPrefs | null,
167|): MusicSelection {
168|  const fallbackId = pickInitialSoundtrack(manifest, null);
169|  const fallbackStyle =
170|    fallbackId !== null
171|      ? (manifest.soundtracks.find((s) => s.id === fallbackId)?.style ?? null)
172|      : null;
173|  const style =
174|    persisted?.style !== null &&
175|    persisted?.style !== undefined &&
176|    styleHasTracks(manifest, persisted.style)
177|      ? persisted.style
178|      : fallbackStyle;
179|  let soundtrackId: string | null = null;
180|  if (style !== null) {
181|    const inStyle = (id: string) =>
182|      manifest.soundtracks.some((s) => s.id === id && s.style === style);
183|    if (
184|      persisted?.soundtrackId !== null &&
185|      persisted?.soundtrackId !== undefined &&
186|      inStyle(persisted.soundtrackId)
187|    ) {
188|      soundtrackId = persisted.soundtrackId;
189|    } else {
190|      soundtrackId = bestCoverageSoundtrack(
191|        manifest,
192|        manifest.soundtracks.filter((s) => s.style === style),
193|      );
194|    }
195|  }
196|  return {
197|    mode: persisted?.mode === "random" ? "random" : "soundtrack",
198|    soundtrackId,
199|    style,
200|  };
201|}
202|
203|// Style change from user action: the session soundtrack becomes the best
204|// coverage soundtrack in the new style, and the track is the best match
205|// for the scene within the new style. Never crosses styles. Null when
206|// the style has no tracks.
207|export function requestStyleChange(
208|  manifest: MusicManifest,
209|  style: string,
210|  scene: SceneSignal | null,
211|  override?: Partial<MusicConfig>,
212|): { soundtrackId: string; track: Track } | null {
213|  const scoped = manifest.tracks.filter((t) => t.style === style && t.playlistOnly !== true);
214|  if (scoped.length === 0) return null;
215|  const config = resolveConfig(override);
216|  const inStyle = manifest.soundtracks.filter(
217|    (s) => s.style === style && scoped.some((t) => t.soundtrack === s.id),
218|  );
219|  const soundtrackId =
220|    bestCoverageSoundtrack(manifest, inStyle) ?? inStyle[0]?.id ?? scoped[0]?.soundtrack;
221|  if (!soundtrackId) return null;
222|  // Rank inside the picked soundtrack first; the style-wide set is only
223|  // the fallback when the home lacks the scene emotion.
224|  const home = scoped.filter((t) => t.soundtrack === soundtrackId);
225|  if (scene === null) {
226|    const first =
227|      [...home].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] ??
228|      ([...scoped].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] as Track);
229|    return { soundtrackId, track: first };
230|  }
231|  const dom = dominantEmotion(scene);
232|  const emoAcross = scoped.filter((t) => t.emotion === dom);
233|  const scope =
234|    home.some((t) => t.emotion === dom) ? home : emoAcross.length > 0 ? emoAcross : scoped;
235|  const track = rankTracks(scene, { ...manifest, tracks: scope }, config)[0] as Track;
236|  return { soundtrackId, track };
